CREATE TABLE IF NOT EXISTS gis_inec_geographic_reconciliation_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), phase text NOT NULL, algorithm_version text NOT NULL, candidate_count integer NOT NULL DEFAULT 0, confirmed_count integer NOT NULL DEFAULT 0, administrative_match_only_count integer NOT NULL DEFAULT 0, insufficient_count integer NOT NULL DEFAULT 0, conflict_count integer NOT NULL DEFAULT 0, not_found_count integer NOT NULL DEFAULT 0, unverified_count integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'RUNNING', created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE TABLE IF NOT EXISTS gis_inec_geographic_reconciliation_decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid NOT NULL REFERENCES gis_inec_geographic_reconciliation_runs(id), candidate_match_id uuid NOT NULL, previous_status text NOT NULL, proposed_status text NOT NULL, decision text NOT NULL, geometry_metadata jsonb NOT NULL DEFAULT '{}'::jsonb, inec_evidence_reference jsonb NOT NULL DEFAULT '{}'::jsonb, spatial_evidence jsonb NOT NULL DEFAULT '{}'::jsonb, errors jsonb NOT NULL DEFAULT '[]'::jsonb, artifact_id uuid, artifact_sha256 text, provenance_reference jsonb NOT NULL DEFAULT '{}'::jsonb, algorithm_version text NOT NULL, decision_fingerprint text NOT NULL UNIQUE, candidate_mutation boolean NOT NULL DEFAULT false, audit_id uuid, decided_at timestamptz NOT NULL DEFAULT now(), UNIQUE(run_id,candidate_match_id));
CREATE INDEX IF NOT EXISTS gis_inec_geo_recon_candidate_idx ON gis_inec_geographic_reconciliation_decisions(candidate_match_id,decided_at DESC);